const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tokens = lines.join("\n").trim().split(/\s+/).map(Number);
let pos = 0;
const n = tokens[pos++];
const q = tokens[pos++];
const raw = tokens.slice(pos, pos + n);
pos += n;
const unique = [...new Set(raw)].sort((a, b) => a - b);
const ids = new Map(unique.map((value, index) => [value, index]));
const values = raw.map(value => ids.get(value));

const blockSize = Math.floor(Math.sqrt(n));
const queries = [];
for (let index = 0; index < q; index++) {
  const left = tokens[pos++] - 1;
  const right = tokens[pos++];
  const block = Math.floor(left / blockSize);
  queries.push({ left, right, block, rightKey: block % 2 ? -right : right, index });
}
queries.sort((a, b) => a.block - b.block || a.rightKey - b.rightKey);

const freq = new Int32Array(unique.length);
const answers = new Int32Array(q);
let lo = 0;
let hi = 0;
let distinct = 0;
for (const { left, right, index } of queries) {
  // The active window is [lo, hi).
  while (lo > left) {
    const value = values[--lo];
    if (freq[value]++ === 0) distinct++;
  }
  while (hi < right) {
    const value = values[hi++];
    if (freq[value]++ === 0) distinct++;
  }
  while (lo < left) {
    const value = values[lo++];
    if (--freq[value] === 0) distinct--;
  }
  while (hi > right) {
    const value = values[--hi];
    if (--freq[value] === 0) distinct--;
  }
  answers[index] = distinct;
}

