import java.io.*;
import java.util.*;

public class Main {
    record Query(int left, int right, int block, int rightKey, int index) {}

    static int nextInt(StreamTokenizer input) throws IOException {
        input.nextToken();
        return (int) input.nval;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer input = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        int n = nextInt(input);
        int q = nextInt(input);
        int[] values = new int[n];
        for (int i = 0; i < n; i++) values[i] = nextInt(input);
        int[] sorted = values.clone();
        Arrays.sort(sorted);
        int unique = 0;
        for (int value : sorted) {
            if (unique == 0 || sorted[unique - 1] != value) sorted[unique++] = value;
        }
        for (int i = 0; i < n; i++) values[i] = Arrays.binarySearch(sorted, 0, unique, values[i]);

        int blockSize = (int) Math.sqrt(n);
        Query[] queries = new Query[q];
        for (int i = 0; i < q; i++) {
            int left = nextInt(input) - 1;
            int right = nextInt(input);
            int block = left / blockSize;
            queries[i] = new Query(left, right, block, block % 2 == 0 ? right : -right, i);
        }
        Arrays.sort(queries, Comparator.comparingInt(Query::block).thenComparingInt(Query::rightKey));

        int[] freq = new int[unique];
        int[] answers = new int[q];
        int lo = 0, hi = 0, distinct = 0;
        for (Query query : queries) {
            // The active window is [lo, hi).
            while (lo > query.left()) {
                int value = values[--lo];
                if (freq[value]++ == 0) distinct++;
            }
            while (hi < query.right()) {
                int value = values[hi++];
                if (freq[value]++ == 0) distinct++;
            }
            while (lo < query.left()) {
                int value = values[lo++];
                if (--freq[value] == 0) distinct--;
            }
            while (hi > query.right()) {
                int value = values[--hi];
                if (--freq[value] == 0) distinct--;
            }
            answers[query.index()] = distinct;
        }

        StringBuilder output = new StringBuilder();
        for (int answer : answers) output.append(answer).append('\n');
        System.out.print(output);
    }
}

