#include <algorithm>
#include <cmath>
#include <iostream>
#include <tuple>
#include <vector>
using namespace std;

struct Query {
    int left, right, block, right_key, index;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<int> values(n);
    for (int& value : values) cin >> value;
    vector<int> sorted = values;
    sort(sorted.begin(), sorted.end());
    sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());
    for (int& value : values) {
        value = lower_bound(sorted.begin(), sorted.end(), value) - sorted.begin();
    }

    int block_size = static_cast<int>(sqrt(n));
    vector<Query> queries;
    queries.reserve(q);
    for (int index = 0; index < q; ++index) {
        int left, right;
        cin >> left >> right;
        --left;
        int block = left / block_size;
        queries.push_back({left, right, block, block % 2 ? -right : right, index});
    }
    sort(queries.begin(), queries.end(), [](const Query& a, const Query& b) {
        return tie(a.block, a.right_key) < tie(b.block, b.right_key);
    });

    vector<int> freq(sorted.size()), answers(q);
    int lo = 0, hi = 0, distinct = 0;
    for (const Query& query : queries) {
        // The active window is [lo, hi).
        while (lo > query.left) {
            int value = values[--lo];
            if (freq[value]++ == 0) ++distinct;
        }
        while (hi < query.right) {
            int value = values[hi++];
            if (freq[value]++ == 0) ++distinct;
        }
        while (lo < query.left) {
            int value = values[lo++];
            if (--freq[value] == 0) --distinct;
        }
        while (hi > query.right) {
            int value = values[--hi];
            if (--freq[value] == 0) --distinct;
        }
        answers[query.index] = distinct;
    }

    for (int answer : answers) cout << answer << '\n';
}
